    entries.push({
      key: name,
      value: yamlRecord,
      ...(isMetadataNameYAML(name) ? {} : { invalid: true }),
    })
    importedItems.push({
      placement,
      name,
      rulePath: itemTraversal.rulePath,
      ...(itemXmlNode === undefined ? {} : { xmlNode: itemXmlNode }),
